*/

let seed;
let epiColors, FG = "deeppink", BG = "navy";
let MAR, GEN_BLUR, SZ;

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	describe("moving gradient squircles with holes morphing between circles and squares");
	frameRate(30);

	noFill();
	stroke(FG);
	strokeWeight(2);
	noStroke();

	init();
}

function init() {
	const { EpiColors } = EpiColorsPckg;
	epiColors = new EpiColors();

	epiColors.getRandomPalette(true);
	FG = epiColors.FG;
	BG = epiColors.BG;

	MAR = max(width, height) * 0.1;

	seed = ~~random(1234321);
	GEN_BLUR = random() < 0.5;
	SZ = ~~(max(width, height) / random(8, 13));
}

function mousePressed() {
	if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0.1*width) init();
}
function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function draw() {
	background(BG);
	gradBackground(FG, BG);
	randomSeed(seed);
	noiseSeed(seed);

	push();
	for (let i = 0; i < 9; i++) {
		const cx = noise(i, frameCount/500) * width; // random(0.15, 0.85) * width;
		const cy = noise(frameCount/400, i) * height; // random(0.15, 0.85) * height;
		const sz = random(0.15, 0.35) * max(width, height);
		const xp = pow(map(sin(i+frameCount/random(50, 150)), -1, 1, 1.414, 3), 2); //  random(1, 7);
		const cx2 = noise(i+0.0375, frameCount/500) * width; // random(0.15, 0.85) * width;
		const cy2 = noise(frameCount/400, i+0.0375) * height; // random(0.15, 0.85) * height;
		const xp2 = pow(map(sin(i+1+frameCount/random(50, 150)), -1, 1, 1.414, 3), 2); //  random(1, 7);

		fill(epiColors.getRandomClr());
		epiColors.getRandomPalette(true);
		let pal = [];
		for (let i = 0; i < ~~random(3, 5); i++) pal.push(epiColors.palette[i % epiColors.palette.length]);

		// fill gradient
		const ctx = drawingContext;
		const linGrad = ctx.createLinearGradient(cx-sz/2, cy-sz/2, cx+sz/2, cy+sz/2);
		// console.log("---> " + i, epiColors.palette)
		for (let i = 0, gradPos = 0; i < pal.length; i++) {
			linGrad.addColorStop(
				map(i, 0, pal.length-1, 0, 1), 
				pal[i]
			);
		}

		if (GEN_BLUR) {		
			ctx.shadowColor = "black";
			ctx.shadowBlur = 6;
			ctx.shadowOffsetX = 4;
			ctx.shadowOffsetY = 4;
		}

		ctx.fillStyle = linGrad;

		const O = 0; // MAR/4;
		beginShape();
			drawSquircle(cx + random(-O, O), cy + random(-O, O), sz, 0.1, xp);
			beginContour();
				drawSquircle(cx2 + random(-O, O), cy2 + random(-O, O), sz - MAR * random(0.9, 1.1), -0.1, xp);
			endContour(CLOSE);
		endShape(CLOSE);
	}
	pop();

	// // noLoop() removed for animation
}

function drawSquircle(cx, cy, size, da = 0.12, exponent = 3) {
  // beginShape();

  let r = size / 2;   // radius (decreases each loop)
  let sA = 0, eA = TAU;
  if (da < 0) {
	  [sA, eA] = [eA, sA];
  }
  let a = sA;
  for (let i = 0; i < TAU/abs(da); i++) {
    // superellipse / squircle formula
    let ca = cos(a);
    let sa = sin(a);

    let x = cx + Math.sign(ca) * pow(abs(ca), 2/exponent) * r;
    let y = cy + Math.sign(sa) * pow(abs(sa), 2/exponent) * r;

    vertex(x, y);

	 a += da;
  }

  // endShape(CLOSE);
}

function gradBackground(c1, c2) {
	// fill gradient
	push();
	fill(BG);
	var ctx = drawingContext;
	var linGrad = ctx.createLinearGradient(0, 0, width, height);
	linGrad.addColorStop(0, c1);
	linGrad.addColorStop(1, c2);
	ctx.fillStyle = linGrad;
	rect(0, 0, width, height);
	pop();
	// muster
	push();
	noStroke();
	// stroke(BG);
	fill(FG);
	for (let y = SZ, j = 0; y < height; y += SZ+SZ, j++) {	
		for (let x = SZ, i = 0; x < width; x += SZ+SZ, i++) {
			if ((i+j)%2) circle(x, y, SZ/4);
		}
	}
	pop();
}
